CREATE TABLE public.extintor_marcas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), comercio_id uuid NOT NULL REFERENCES public.comercio(id), nombre text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(comercio_id,nombre));
CREATE TABLE public.extintor_clases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), comercio_id uuid NOT NULL REFERENCES public.comercio(id), nombre text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(comercio_id,nombre));
CREATE TABLE public.extintores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), comercio_id uuid NOT NULL REFERENCES public.comercio(id), cliente_id uuid NOT NULL REFERENCES public.clientes(id), numero_extintor text NOT NULL, numero_serie text NOT NULL, marca_id uuid REFERENCES public.extintor_marcas(id) ON DELETE SET NULL, clase_id uuid REFERENCES public.extintor_clases(id) ON DELETE SET NULL, anio_prueba_hidraulica integer, fecha_ultima_recarga date, fecha_proxima_recarga date, anio_fabricacion integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(comercio_id,numero_extintor));
CREATE INDEX idx_extintores_comercio_cliente ON public.extintores(comercio_id,cliente_id);
CREATE INDEX idx_extintores_comercio_proxima_recarga ON public.extintores(comercio_id,fecha_proxima_recarga);
ALTER TABLE public.extintor_marcas ENABLE ROW LEVEL SECURITY; ALTER TABLE public.extintor_clases ENABLE ROW LEVEL SECURITY; ALTER TABLE public.extintores ENABLE ROW LEVEL SECURITY;
CREATE POLICY extintor_marcas_tenant ON public.extintor_marcas FOR ALL TO authenticated USING (public.user_belongs_to_comercio(comercio_id)) WITH CHECK (public.user_belongs_to_comercio(comercio_id));
CREATE POLICY extintor_clases_tenant ON public.extintor_clases FOR ALL TO authenticated USING (public.user_belongs_to_comercio(comercio_id)) WITH CHECK (public.user_belongs_to_comercio(comercio_id));
CREATE POLICY extintores_tenant ON public.extintores FOR ALL TO authenticated USING (public.user_belongs_to_comercio(comercio_id)) WITH CHECK (public.user_belongs_to_comercio(comercio_id));
CREATE TRIGGER update_extintores_updated_at BEFORE UPDATE ON public.extintores FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
